(function () {
  const F = W.F;
  kit.scene('parlor', {
    init(kit) {
      const M = W.MOODS.parlorRose;
      kit.stage.append(kit.h(F.frame(W.bg.parlor(M) + W.prop.settee(960, 860, 1, '#C9B48A') + W.prop.piano(1350, 820, 0.8) + W.prop.keroLamp(420, 600, 1, 0) +
        ['madam', 'girl1', 'girl2', 'pianist', 'baron', 'miner'].map((k) => F.who('lk-' + k, k)).join(''), '', '')));
      this.p = ['madam', 'girl1', 'girl2', 'pianist', 'baron', 'miner'].map((k) => W.bindPerson(kit.stage, 'lk-' + k)); this.cam = kit.stage.querySelector('.cam');
    },
    render(t) { F.framing(this.cam, 1, 960, 540);
      const xs = [480, 820, 1060, 1330, 1600, 1800];
      this.p.forEach((m, i) => W.posePerson(m, { x: xs[i], y: 990, s: 1.7, expr: ['smug', 'neutral', 'happy', 'neutral', 'smug', 'worried'][i] })); },
  });
})();
